function solve(A,b){A=A.map((r,i)=>[...r,b[i]]);const n=b.length;for(let i=0;i<n;i++){let k=i;for(let j=i+1;j<n;j++)if(Math.abs(A[j][i])>Math.abs(A[k][i]))k=j;[A[i],A[k]]=[A[k],A[i]];if(Math.abs(A[i][i])<1e-12)throw Error('定位点重合或接近共线');const d=A[i][i];for(let c=i;c<=n;c++)A[i][c]/=d;for(let j=0;j<n;j++){if(j===i)continue;const f=A[j][i];for(let c=i;c<=n;c++)A[j][c]-=f*A[i][c];}}return A.map(r=>r[n]);}
