function edgePoints(q,start=null,end=null){if(!validQuad(q))throw Error('无法生成边线定位点');const out=[];for(let i=0;i<4;i++){const a=q[i],b=q[(i+1)%4];const len=Math.hypot(b.x-a.x,b.y-a.y),short=Math.min(...q.map((p,j)=>Math.hypot(q[(j+1)%4].x-p.x,q[(j+1)%4].y-p.y))),inset=Math.min(.12,short*.065/len);for(const t of [start??inset,end??(1-inset)])out.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}return out;}
